import { createSlice } from '@reduxjs/toolkit'
import { initialState } from './initialState'
import { TypeOneAnalysis } from 'diabetes-calculator-suggestions'
import { updateEffectProfilesFromSettings } from './effectProfiles'


const doUnitMath = (state, stateUpdate, records, settings, effectProfiles) => {

  Object.assign(state, stateUpdate)

  effectProfiles = updateEffectProfilesFromSettings(settings, effectProfiles)

  const t1a = new TypeOneAnalysis()
  const timeline = t1a
    .setEffectProfiles({ data: effectProfiles })
    .timeline({ data: records })
    .limit('72:00')

  const now = Date.now()

  const calculationType = state.hasCarbUnits && state.hasBgUnits
    ? 'both'
    : state.hasCarbUnits
      ? 'carbs'
      : state.hasBgUnits
        ? 'correction'
        : null

  if (!state.ui_isTaken) {
    timeline.add({
      ...state,
      date: now,
      calculationType,
      bgDistance: 0,
      bgUnits: 0,
      carbUnits: 0,
      totalUnits: 0,
      adjustedTotalUnits: 0,
      roundedAdjustedTotalUnits: 0
    })
  }

  timeline.groupEffects({
    maxDurationHHmm: '00:15',
    maxBgBolusDistanceBeforeStartHHmm: '00:05',
    maxBgBolusDistanceAfterStartHHmm: '00:05',
    maxBgBolusDistanceBeforeEndHHmm: '00:20',
    maxBgBolusDistanceAfterEndHHmm: '00:40',
    overlappingPreviousIntensityCutoff: 0.1
  })

  const analysis = timeline.analysis()
  const {
    bgUnits,
    carbUnits,
    totalUnits,
    roundedAdjustedTotalUnits
  } = analysis.calculateUnits({
    ms: now,
    ...state
  })

  Object.assign(state, {
    calculationType,
    bgDistance: 0,
    bgUnits,
    carbUnits,
    totalUnits,
    roundedAdjustedTotalUnits
  })

}

const insulinUnitsSlice = createSlice({
  name: 'insulinUnits',
  initialState: initialState.insulinUnits,
  reducers: {
    allInsulinUnitsChanged(state, action) {
      const records = action.records
      const settings = action.settings
      const effectProfiles = action.effectProfiles
      doUnitMath(state, action.payload, records, settings, effectProfiles)
      state.ui_isChanged = true
      localStorage.setItem('insulinUnits', JSON.stringify(state, null, 2))
    },
    markChanged(state) {
      state.ui_isChanged = true
      localStorage.setItem('insulinUnits', JSON.stringify(state, null, 2))
    },
    markTaken(state, action) {
      state.ui_isTaken = true
      localStorage.setItem('insulinUnits', JSON.stringify(state, null, 2))
    },
    reset(state) {
      state.ui_isChanged = false
      localStorage.setItem('insulinUnits', JSON.stringify(state, null, 2))
    }
  }
})

export const {
  allInsulinUnitsChanged,
  markChanged,
  markTaken,
  reset
} = insulinUnitsSlice.actions

export default insulinUnitsSlice.reducer
