function decimalToFraction(decimal) {
  // Handle whole numbers
  if (Number.isInteger(decimal)) return decimal.toString();

  const tolerance = 1.0E-2; // Adjust tolerance for precision needs
  let numerator = 1;
  let denominator = 1;
  let error = Math.abs(decimal - (numerator / denominator));

  for (let d = 1; d <= 50; d++) { // Limit denominator for practical purposes
    for (let n = 0; n <= d; n++) {
      const currentError = Math.abs(decimal - (n / d));
      if (currentError >= error) continue
      error = currentError;
      numerator = n;
      denominator = d;
    }
  }

  if (error < tolerance) return `${numerator}/${denominator}`;
  // If no simple fraction found, return the decimal as a string
  return decimal.toString();
}


function integerToWords(num) {
  const ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"];
  const teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"];
  const tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"];

  if (num === 0) return "zero";
  if (num < 10) return ones[num];
  if (num < 20) return teens[num - 10];
  if (num < 100) return tens[Math.floor(num / 10)] + (num % 10 !== 0 ? "-" + ones[num % 10] : "");
  // Extend for larger numbers if needed
  return num.toString(); // Fallback for numbers > 99
}

function fractionToParts(fractionString) {
  const parts = fractionString.split('/');
  const numerator = parseInt(parts[0]);
  const denominator = parseInt(parts[1]);
  return { numerator, denominator }
}

function fractionToEnglish(fractionString) {
  const {numerator, denominator} = fractionToParts(fractionString)
  let numeratorText = integerToWords(numerator);
  let denominatorText = "";

  // Special cases for denominators
  if (denominator === 2) {
    denominatorText = "half";
    if (numerator > 1) denominatorText = "halves";
  } else if (denominator === 3) {
    denominatorText = "third";
    if (numerator > 1) denominatorText = "thirds";
  } else if (denominator === 4) {
    denominatorText = "quarter";
    if (numerator > 1) denominatorText = "quarters";
  } else {
    denominatorText = integerToWords(denominator) + (numerator > 1 ? "ths" : "th"); // General case
  }
  return `${numeratorText} ${denominatorText}`;
}


function numberToWords(numberString) {
  numberString = String(numberString)
  const isFraction = numberString.includes('/')
  const isDecimal = (!isFraction && numberString.includes('.'))
  const isInteger = (!isDecimal && !isFraction)
  if (isInteger) {
    // If it's a whole number or decimal not converted to fraction
    return integerToWords(parseFloat(numberString));
  }

  let integerPrefix = ''
  let number
  if (isFraction) {
    const {numerator, denominator} = fractionToParts(numberString)
    number = numerator/denominator
  } else if (isDecimal) {
    number = parseFloat(numberString)
    if (Number.isInteger(number)) return integerToWords(number)
  }
  const floored = Math.floor(number)
  if (number - floored === 0) {
    return integerToWords(number)
  }
  if (floored !== number) {
    if (floored !== 0) {
      integerPrefix = integerToWords(floored) + " and "
    }
    numberString = decimalToFraction(number - floored)
    if (numberString.includes('.')) return number;
  }
  return integerPrefix + fractionToEnglish(numberString)
}

export {
  decimalToFraction,
  integerToWords,
  fractionToEnglish,
  numberToWords
}