// import Time from './Time.js'

export default class DateTimeRange {
  /**
     * @param {Object} options
     * @param {number} options.startMs
     */
  constructor ({ startMs = null, endMs = null }) {
    this.startMs = startMs
    this.endMs = endMs ?? startMs
  }

  set startMs (value) {
    this._startMs = value
  }

  /** @type {DateTime} */
  get startMs () {
    return this._startMs
  }

  set endMs (value) {
    this._endMs = value
  }

  /** @type {DateTime} */
  get endMs () {
    return this._endMs
  }

  /** @type {Time} */
  get durationMs () {
    return this.endMs - this.startMs // new Time({ ms: this.endMs - this.startMs })
  }

  /** @type {boolean} */
  get hasStartEnd () {
    return Boolean(this.startMs && this.endMs)
  }

  /**
   * @param {number} ms
   * @returns {boolean}
   */
  isMsInRange (ms) {
    return (Number(ms) >= Number(this.startMs) && Number(ms) <= Number(this.endMs))
  }

  /**
   * @param {number} ms
   * @returns {boolean}
   */
  isMsAfterRange (ms) {
    return (Number(ms) > Number(this.endMs))
  }

  /**
   * @param {number} ms
   * @returns {boolean}
   */
  isMsBeforeRange (ms) {
    return (Number(ms) < Number(this.startMs))
  }
}
