export default class Day {
  /**
   * @param {Object} options
   * @param {number} options.ms
   */
  constructor ({ ms }) {
    this.ms = ms
    // this.str = new Date(this.ms).toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', hour: 'numeric', minute: 'numeric' })
  }

  set ms (value) {
    this._ms = value
  }

  /** @type {number} */
  get ms () {
    return this._ms
  }

  [Symbol.toPrimitive] (hint) {
    if (hint === 'number' || hint === 'default') {
      return this.ms
    }
    return this.str
  }

  /** @type {number} */
  static get ONE_DAY () {
    return (this._ONE_DAY = this._ONE_DAY ?? 24 * 60 * 60 * 1000)
  }
}
