import Amount from './Amount.js'

export default class BgAmount extends Amount {
/**
   * @param {Object} options
   * @param {number} options.target
   * @param {number} options.amount
   * @param {number} options.startMs
   */
  constructor ({ target, amount, startMs }) {
    super({ amount, startMs })
    this.target = target
  }

  set target (value) {
    this._target = value
  }

  /** @type {number} */
  get target () {
    return this._target
  }
}
