import { langs } from './lang/langs';
import React, { useEffect } from 'react';
import {
  createHashRouter,
  RouterProvider,
  createRoutesFromElements,
  Routes,
  Route,
  Outlet,
  Link,
  useNavigate,
  useLocation
} from "react-router-dom";

import { allSettingsChanged } from './store/settings';
import { useDispatch, useSelector } from 'react-redux';
import { InsulinUnits } from './InsulinUnits';
import { ProportionateCarbs } from './ProportionateCarbs';
import { Records } from './Records';
import { Settings } from './Settings'
import { Warning } from './Warning'
import { About } from './About'

import {
  AppBar,
  List,
  IconButton,
  Toolbar,
  Divider,
  ListItem,
  ListItemIcon,
  ListItemText,
  Drawer,
  Typography
} from '@mui/material'
import {
  Settings as MenuIcon,
  LocalHospitalOutlined as FoodInsulinIcon,
  Settings as SettingsIcon,
  SystemUpdate as SystemUpdateIcon,
  PriorityHigh as WarningIcon,
  QuestionMark as AboutIcon,
  ArrowBack as BackIcon,
  TableChart as RecordsIcon,
  Close as CloseIcon
} from '@mui/icons-material'



function BackButton() {
  const { pathname } = useLocation();
	const navigate = useNavigate();
  return pathname !== '/insulinunits' && pathname !== '/' ?
  <IconButton
      color="inherit"
    aria-label="open drawer"
    edge="start"
    onClick={() => navigate(-1)}
  >
    <BackIcon />
  </IconButton>
  : null
}

function SettingsButton() {
  const { pathname } = useLocation();
  return (pathname !== '/settings' &&
    pathname !== '/about' &&
    pathname !== '/warning' &&
    pathname !== '/records') ?
    <IconButton
    color="inherit"
    aria-label="open drawer"
    component={Link} to='/settings'
    edge="start"
  >
    <MenuIcon />
  </IconButton>
  :null
}

function InsulinUnitsMenu() {
  const { pathname } = useLocation();
  return pathname === '/insulinunits' || pathname === '/' ?
  <React.Fragment>
    <IconButton
        color="inherit"
      aria-label="open drawer"
      edge="start"
      component={Link} to='/about'
    >
      <AboutIcon />
    </IconButton>
    <IconButton
      color="inherit"
      aria-label="open drawer"
      edge="start"
      component={Link} to='/records'
    >
      <RecordsIcon />
    </IconButton>
  </React.Fragment>
  : null
}

function SettingsMenu() {
  const { pathname } = useLocation();
  return pathname === '/settings' ?
  <React.Fragment>
  </React.Fragment>
  : null
}


const router = createHashRouter(createRoutesFromElements(
  <Route path='/' element={<Layout />}>
    <Route path='insulinunits?' element={<InsulinUnits />}/>
    <Route path="records" element={<Records />}/>
    <Route path="proportionatecarbs" element={<ProportionateCarbs />}/>
    <Route path="settings" element={<Settings />}/>
    <Route path="about" element={<About />}/>
    <Route path="warning" element={<Warning />}/>
  </Route>
));

function Layout() {

  const view = useSelector(state => state.view)

  return (<div className='App_outer'>
      <div className="App">
        <AppBar>
          <Toolbar>
            <BackButton />
            <Typography variant="h6" noWrap>
              {view.title}
            </Typography>
            <InsulinUnitsMenu />
            <SettingsMenu />
            <SettingsButton />
          </Toolbar>
        </AppBar>

        <main>

            <Outlet />

        </main>
      </div>
    </div>
  )
}

function App() {
  const dispatch = useDispatch();

  const settings = useSelector(state => state.settings)
  useEffect(() => {
    (async () => {
      const response = await fetch('./manifest.json');
      const manifest = await response.json();
      console.log(`Installed: ${settings.version}, Manifest: ${manifest.version}`)
      dispatch(allSettingsChanged({ needsUpdating: (manifest.version !== settings.version) }))
    })();
  })

  return <RouterProvider router={router} />;
}

export default App;
