import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux'
import { Button } from '@mui/material';
import { titleChanged } from './store/view';
import { resetRecords, removeRecordIndex, uploadJSON } from './store/records'
import {
  Autorenew as AutorenewIcon,
  GetApp as DownloadIcon,
  Upload as UploadIcon
} from '@mui/icons-material'
import { langs } from './lang/langs';
import { Label, ReferenceLine, CartesianGrid, Scatter, ZAxis, XAxis, YAxis, Tooltip, Legend, Line, Bar, ComposedChart, ResponsiveContainer } from 'recharts';

export const Records = () => {

  const insulinUnits = useSelector(state => state.insulinUnits)
  const state = useSelector(state => state.records)
  const settings = useSelector(state => state.settings)
  const lang = langs[settings.lang]
  const dispatch = useDispatch()

  useEffect(() => {
    dispatch(
      titleChanged(lang.recordsTitle)
    )
  })

  function removeRecord (index) {
    dispatch(removeRecordIndex(index))
  }

  const downloadData = state => {
    const a = document.createElement('a')
    a.setAttribute('download', `${new Date().toISOString()}_records.json`)
    const json = window.btoa(JSON.stringify(state, null, 2))
    a.setAttribute('href', `data:text/json;base64,${json}`)
    a.click()
  }

  const uploadData = async (event, state) => {
    const data = await new Promise(resolve => {
      const objectURL = URL.createObjectURL(event.target.files[0]);
      const reader = new FileReader()
      reader.addEventListener('load', () => {
        URL.revokeObjectURL(objectURL)
        resolve(reader.result)
      })
      reader.readAsText(event.target.files[0])
    })
    const uploadedJSON = JSON.parse(data)
    dispatch(uploadJSON(uploadedJSON))
  }

  const getIntensity = (time, value, halflifeHHmm) => {
    if (!halflifeHHmm) return 0
    if (halflifeHHmm.length === 1) halflifeHHmm = `00:0${halflifeHHmm}`
    if (halflifeHHmm.length === 2) halflifeHHmm = `00:${halflifeHHmm}`
    if (halflifeHHmm.length === 4) halflifeHHmm = `0${halflifeHHmm}`
    const halfLifeMs = Date.parse('1970-01-01T' + halflifeHHmm + 'Z'); // time it peaks and then interval it halves
    const now =  Date.now();
    const gap = now - time;
    const passedIntervals = (gap / halfLifeMs)
    if (passedIntervals > 10) return 0
    const ratio = Math.pow(2, passedIntervals)
    const intensity = 1 / ratio
    if (value * intensity < 1) return 0
    return intensity
  }

  const now = Date.now()
  const oneHour = 60 * 60 * 1000
  const endDate = now

  const midnight = ((Math.floor(now / (oneHour * 24)) * (oneHour * 24)) - endDate) / oneHour

  const data = state.map(row => {
    return {
      date: row.data,
      hour: (row.date - endDate) / oneHour,
      units: row.roundedAdjustedTotalUnits,
      carbs: row.consumedCarbs,
      glucose: row.currentBg
    }
  }).filter(row => row.hour > -24)

  return (
    <React.Fragment>
      <div className="records insulinunits__output output__container" style={{position:'sticky', top: 0, left: 0}}>
        <ResponsiveContainer width={"100%"} height={250}>
        <ComposedChart
            data={data}
            margin={{
              top: 2,
              right: 2,
              bottom: 2,
              left: 2
            }}
        >
          <XAxis dataKey="hour" type="number" domain={[-24, 0]} interval={-2}>
              <Label value="last 24 hours" offset={-6} position="bottom" />
            </XAxis>
          <YAxis yAxisId='left'>
            <Label value="carbs" angle={-90} offset={6} position="center" />
          </YAxis>
          <YAxis yAxisId="right" orientation='right' domain={[0, 24]}>
            <Label value="units and glucose" angle={90} offset={6} position="center" />
          </YAxis>

          <ZAxis range={[30, 31]} />
          <Tooltip labelFormatter={(value, name, props) => {
            return new Date(endDate+(value*oneHour)).toLocaleDateString("en-GB", { weekday: 'short', day: 'numeric', month: 'short', hour: 'numeric', minute: 'numeric' })
          }}/>
          <Legend />
          <ReferenceLine yAxisId="left" x={String(midnight)} stroke="grey" label="" />
          <ReferenceLine yAxisId="right" y={insulinUnits.targetBg} stroke="grey" label="" />
          <Bar yAxisId="left" dataKey="carbs" fill="green" />
          <Scatter yAxisId="right" type="monotone" dataKey="glucose" line={false} fill="white" />``
          <Bar yAxisId="right" dataKey="units" fill="red" />
        </ComposedChart>
        </ResponsiveContainer>
      </div>
    <section className="records screen__container">



      <div className="records__buttons">
        <Button
          className='button top__button'
          onClick={
            () => {
              dispatch(resetRecords(state))
            }
          }
        >
          <AutorenewIcon />
          &nbsp;{lang.recordsResetButtonText}
        </Button>
        <Button
          className='button top__button'
          onClick={
            () => {
              downloadData(state)
            }
          }
        >
          <DownloadIcon />
          &nbsp;{lang.recordsDownloadButtonText}
        </Button>
        <input style={{display: 'none'}} id="fileupload" type="file" name="fileupload" accept='application/json' onChange={event => {
          if (!event.target.value) return
          uploadData(event, state)
        }} />
        <Button
          className='button top__button'
          onClick={() => {
            document.querySelector('#fileupload').value = null
            document.querySelector('#fileupload').click()
          }}
        >
          <UploadIcon />
          &nbsp;{lang.recordsUploadButtonText}
        </Button>
      </div>

      <div className="records_input input__group">
          <table>
            <thead style={{position:'sticky', top: 255, left: 0, background: 'black', zIndex: 1 }}>
            <tr>
              <th>Date</th>
              <th>Glucose</th>
              <th>Carbs</th>
              <th>Units</th>
              <th>For</th>
              <th></th>
            </tr>
            </thead>
            <tbody>
            {state.map((row, index) => {
              const unitsBackgroundColor =
                !row.roundedAdjustedTotalUnits
                  ? 'transparent'
                  : `rgba(255,0,0, ${getIntensity(row.date, row.roundedAdjustedTotalUnits, settings.bolusHalfLife)})`
              const carbsBackgroundColor =
                !row.consumedCarbs
                  ? 'transparent'
                  : `rgba(0,128,0, ${getIntensity(row.date, row.consumedCarbs, settings.carbsHalfLife)})`
              return <tr key={index}>
                <td>{new Date(row.date).toLocaleDateString("en-GB", { weekday: 'short', day: 'numeric', month: 'short', hour: 'numeric', minute: 'numeric' })}</td>
                <td>{row.currentBg}</td>
                <td style={{backgroundColor: carbsBackgroundColor}}>{row.consumedCarbs}</td>
                <td style={{ backgroundColor: unitsBackgroundColor }}>{row.calculationType === null ? 'none' : row.roundedAdjustedTotalUnits}</td>
                <td>{row.calculationType === null ? 'n/a' : row.calculationType}</td>
                <td><Button style={{minWidth: '12px'}} onClick={removeRecord.bind(this, index)}>x</Button></td>
              </tr>
            })}
            </tbody>
          </table>

      </div>

    </section>
  </React.Fragment>
  )
}
