import { evaluate } from 'mathjs'

export default function doStringMath(value) {
  let str = String(value)
  if (str.includes(':')) return str
  str = str.replace(/x/i, '*')
  try {
    const result = evaluate(str)
    const type = typeof result
    if (type === 'number') return result
  } catch (err) {
  }
  return value
}
