import { createSlice } from '@reduxjs/toolkit'
import { initialState } from './initialState'

const effectProfilesSlice = createSlice({
  name: 'effectProfiles',
  initialState: initialState.effectProfiles,
  reducers: {

  }
})

export const {
} = effectProfilesSlice.actions

export default effectProfilesSlice.reducer


export function updateEffectProfilesFromSettings (settings, effectProfiles) {
  effectProfiles = JSON.parse(JSON.stringify(effectProfiles))
  const bolus = effectProfiles.find(effect => effect.name === 'bolus')
  const mostlySimpleCarbs = effectProfiles.find(effect => effect.name === 'mostlySimpleCarbs')
  Object.assign(bolus.halfLifes[0], {
    "onsetHHmm": settings.bolusOnset || "00:03",
    "peakHHmm": settings.bolusPeak || "00:40",
    "halfLifeHHmm": settings.bolusHalfLife || "00:60",
    "durationHHmm": settings.bolusDuration || "07:00",
  })
  Object.assign(mostlySimpleCarbs.halfLifes[0], {
    "onsetHHmm": settings.carbsOnset || "00:03",
    "peakHHmm": settings.carbsPeak || "00:40",
    "halfLifeHHmm": settings.carbsHalfLife || "00:60",
    "durationHHmm": settings.carbsDuration ||"07:00",
  })
  return effectProfiles
}
