import { Label, ReferenceLine, CartesianGrid, XAxis, YAxis, ZAxis, Tooltip, Legend, Line, Bar, ComposedChart, ResponsiveContainer, Dot, Scatter, Text } from 'recharts';
import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux'
import { langs } from './lang/langs';
import { TypeOneAnalysis } from 'diabetes-calculator-suggestions'
import { updateEffectProfilesFromSettings } from './store/effectProfiles';

export default function SmallPredictions() {
  const insulinUnits = useSelector(state => state.insulinUnits)
  const state = useSelector(state => state.records)
  let effectProfiles = useSelector(state => state.effectProfiles)
  const settings = useSelector(state => state.settings)

  effectProfiles = updateEffectProfilesFromSettings(settings, effectProfiles)

  const lang = langs[settings.lang]

  const now = Date.now()
  const oneHour = 60 * 60 * 1000

  const t1a = new TypeOneAnalysis()
  const timeline = t1a
    .setEffectProfiles({ data: effectProfiles })
    .timeline({ data: state })
    .limit('72:00')

    const {
      ui_calculationType,
      consumedCarbs,
      currentBg,
      minimumUnits,
      carbsPerUnit,
      bgPerUnit,
      targetBg,
      bgDistance,
      bgUnits,
      carbUnits,
      totalUnits,
      adjustedTotalUnits,
      roundedAdjustedTotalUnits
    } = insulinUnits

  if (!insulinUnits.ui_isTaken) {
    timeline.add({
      date: now,
      calculationType: ui_calculationType,
      consumedCarbs,
      currentBg,
      minimumUnits,
      carbsPerUnit,
      bgPerUnit,
      targetBg,
      bgDistance,
      bgUnits,
      carbUnits,
      totalUnits,
      adjustedTotalUnits,
      roundedAdjustedTotalUnits
    })
  }

  timeline.groupEffects({
    maxDurationHHmm: '00:15',
    maxBgBolusDistanceBeforeStartHHmm: '00:05',
    maxBgBolusDistanceAfterStartHHmm: '00:05',
    maxBgBolusDistanceBeforeEndHHmm: '00:20',
    maxBgBolusDistanceAfterEndHHmm: '00:40',
    overlappingPreviousIntensityCutoff: 0.1
  })

  const analysis = timeline.analysis({ minimumDurationHHmm: '06:00 '})

  const chartHours = 4
  const intervalMs = (20 * 60 * 1000)
  const startMs = now // Math.floor(now / intervalMs) * intervalMs
  const timesCount = Math.ceil(((now + (chartHours * oneHour)) - startMs) / intervalMs)
  const endMs = (timesCount * intervalMs) + startMs

  let json = []
  let lastBg = null
  if (timesCount) {

    const timesMs = new Array(timesCount).fill(0).map((value, index) => {
      const atMs = (intervalMs * index) + startMs
      return atMs
    })

    // todo: Change insulin efficiency to "exercise/sickness event"
    //   add event to output
    // todo: delay insulin / food by 5 minute intervals UI
    // todo: corrective insulin for < 0 values should be "take x carbs"
    // todo: sort out startBg on bg prediction line 50 (Bg.js)
    // todo: sort out startBg on bolus prediction line 147 (Bolus.js)
    // todo: turn off corrections selector on overlapping effects where correction has already been applied
    //  correct final blood glucose where necessary
    // todo: apply insulin efficiency to basal insulin (need bg per unit on basal?)
    // todo: add basal stuff to settings and calculator
    // todo: work out error margin for prediction vs actual over time and do something about it
      // todo: use actual bg outside of peak effects?
      // warn that bg change indicates input / reading error
      // warn that bg is rising / falling much faster than expected
      // warn that an unrecorded effect is in progress


    let lastActual = 0
    json = timesMs.map(ms => {
      // todo: check that this works with many intersecting
      lastBg = analysis.getBgAt({ ms }) ?? lastBg
      lastActual = timeline.findNearestBg(ms, intervalMs / 2, intervalMs / 2)?.amount ?? ''
      return {
        date: ms,
        bg: lastBg ? Number(Number(lastBg).toFixed(2)) : null,
        actual: lastActual ? Number(Number(lastActual).toFixed(2)) : null,
        bolus: Number(Number(analysis.getBolusAt({ ms })).toFixed(2)),
        carbs: Number(Number(analysis.getCarbsAt({ ms })).toFixed(2))
      }
    })
  }

  const hour2 = now + (oneHour * 2)
  const hour4 = now + (oneHour * 4)
  const hour6 = now + (oneHour * 6)
  const hour8 = now + (oneHour * 8)

  const bG2h = analysis.getBgAt({ ms: now + (2 * oneHour) })
  const bG4h = analysis.getBgAt({ ms: now + (4 * oneHour) })
  const bG8h = analysis.getBgAt({ ms: now + (8 * oneHour) })

  return (
    <div>
    <div style={{textAlign: 'right', fontSize:'small'}}>2h: {Number(bG2h).toFixed(1)}, 4h: {Number(bG4h).toFixed(1)}, 8h: {Number(bG8h).toFixed(1)}</div>
    <ResponsiveContainer width={"100%"} height={48}>
        <ComposedChart
            data={json}
            margin={{
              top: 2,
              right: 2,
              bottom: 2,
              left: 2
            }}
        >
          <XAxis dataKey="date" type="number" domain={[startMs, endMs]} tickCount={0}  hide={true}>
            </XAxis>
          <YAxis yAxisId='left' tickCount={0} domain={[dataMin => Math.min(0, dataMin), dataMax => Math.max(10, dataMax)]} hide={true}>
          </YAxis>
          <YAxis yAxisId='left1' reversed={false} tickCount={0} domain={[dataMin => Math.min(0, dataMin), dataMax => Math.max(10, dataMax)]} hide={true}>
          </YAxis>
          <YAxis yAxisId="right" orientation='right' domain={[dataMin => Math.min(0, dataMin), dataMax => Math.max(18, dataMax)]} tickCount={0} hide={true}>
          </YAxis>
          <ZAxis range={[30, 31]} />
          <ReferenceLine yAxisId="right" x={startMs} stroke="#303030" label="" strokeWidth={3}/>
          <ReferenceLine yAxisId="right" x={hour2} stroke="#303030" label="" strokeWidth={3}/>
          <ReferenceLine yAxisId="right" x={hour4} stroke="#303030" label="" strokeWidth={3}/>
          <ReferenceLine yAxisId="right" x={hour6} stroke="#303030" label="" strokeWidth={3}/>
          <ReferenceLine yAxisId="right" x={hour8} stroke="#303030" label="" strokeWidth={3}/>
          <Line yAxisId="left" dataKey="carbs" stroke="#19d224" dot={false} strokeWidth={3}/>
          <Line yAxisId="left1" dataKey="bolus" stroke="#c90000" dot={false} strokeWidth={3}/>
          <ReferenceLine yAxisId="right" y={insulinUnits.targetBg} stroke="grey" label="" strokeWidth={3}/>
          <Line yAxisId="right" type="monotone" dataKey="bg" stroke="white" dot={false} strokeWidth={3}/>
          <Scatter yAxisId="right" type="monotone" dataKey="actual" line={false} fill="white"/>
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  )
}

