import { createSlice } from '@reduxjs/toolkit'
import { initialState } from './initialState'

const recordsSlice = createSlice({
  name: 'records',
  initialState: initialState.records,
  reducers: {
    uploadJSON(state, action) {
      state.length = 0
      state.push(...action.payload)
      localStorage.setItem('records', JSON.stringify(state, null, 2))
    },
    recordTakeInsulin(state, action) {
      const {
        ui_calculationType,
        consumedCarbs,
        currentBg,
        minimumUnits,
        carbsPerUnit,
        bgPerUnit,
        targetBg,
        bgDistance,
        bgUnits,
        carbUnits,
        totalUnits,
        adjustedTotalUnits,
        roundedAdjustedTotalUnits
      } = action.payload
      state.unshift({
        date: Date.now(),
        calculationType: ui_calculationType,
        consumedCarbs,
        currentBg,
        minimumUnits,
        carbsPerUnit,
        bgPerUnit,
        targetBg,
        bgDistance,
        bgUnits,
        carbUnits,
        totalUnits,
        adjustedTotalUnits,
        roundedAdjustedTotalUnits
      })
      localStorage.setItem('records', JSON.stringify(state, null, 2))
    },
    resetRecords(state) {
      state.length = 0
      localStorage.setItem('records', JSON.stringify(state, null, 2))
    },
    removeRecordIndex(state, action) {
      state.splice(action.payload, 1)
      localStorage.setItem('records', JSON.stringify(state, null, 2))
    }
  }
})

export const {
  uploadJSON,
  recordTakeInsulin,
  recordNoInsulin,
  resetRecords,
  removeRecordIndex
} = recordsSlice.actions

export default recordsSlice.reducer
