import BolusEffects from './BolusEffects.js'

export default class CarbUnitEffects extends BolusEffects {
  get configuredCarbsPerUnit () {
    const { carbUnits } = this
    const totalRatio = carbUnits.reduce((total, effect) => total + effect.effectRatio.carbsPerUnit, 0)
    return totalRatio / carbUnits.length
  }

  calculateCarbsPerUnit (bgPerUnit) {
    const { carbsEaten, carbUnitsTaken, bgUnitsTaken, endBg, startBg } = this

    const expectedEndBg = this.getBgAt(endBg.startMs)

    console.log('calculateCarbsPerUnit carb', endBg.amount, expectedEndBg.amount)

    // where did the actions we take
    const actionedBgCorrectionDrop = bgUnitsTaken * (bgPerUnit * -1)
    const actionedBgCarbDrop = carbUnitsTaken * (bgPerUnit * -1)
    const actionedBgDiff = actionedBgCarbDrop - actionedBgCorrectionDrop
    // what was the measured bg difference
    const measuredBgDiff = (endBg - startBg)
    // recalculate the ratio
    const calculatedAdjustmentRatio = actionedBgDiff / measuredBgDiff
    const newCarbsPerUnit = (carbUnitsTaken * calculatedAdjustmentRatio) / carbsEaten
    return newCarbsPerUnit
  }
}
