import BolusEffects from './BolusEffects.js'

export default class BgUnitEffects extends BolusEffects {
  get configuredBgPerUnit () {
    const { bgUnits } = this
    const totalRatio = bgUnits.reduce((total, effect) => total + effect.effectRatio.bgPerUnit, 0)
    return totalRatio / bgUnits.length
  }

  calculateBgPerUnit () {
    const { bgUnitsTaken, endBg, startBg, configuredBgPerUnit, configuredCarbsPerUnit } = this

    const expectedEndBg = this.getBgAt({
      ms: endBg.startMs,
      startBg,
      carbPerUnit: configuredCarbsPerUnit,
      bgPerUnit: configuredBgPerUnit
    })

    console.log('calculateBgPerUnit bg', endBg.amount, expectedEndBg.amount)

    // where did the actions we take compensate for
    const actionedBgDiff = (expectedEndBg - startBg)
    // what was the actual outcome
    const actualBgDiff = (endBg - startBg)
    // what was the proportional difference
    const differential = actionedBgDiff / actualBgDiff
    // calculate new value
    const newBgPerUnit = bgUnitsTaken * differential * -1
    return newBgPerUnit
  }
}
