export default function makeOnBlur(defaults, dispatch, action, { noui = false } = {}, attrs) {
  return (name, event) => {
    const value = event.target.value
    if (value !== "") return;
    const act = action(
      noui
      ? {
        [name]: defaults[name],
      }
      : {
        [name]: defaults[name],
        [`ui_${name}`]: defaults[name]
      }
    )
    Object.assign(act, attrs ?? {})
    dispatch(
      act
    )
  }
}
