import DateTimeRange from './DateTimeRange.js'
import Time from './Time.js'

export default class EffectProfileHalfLife extends DateTimeRange {
  /**
   * @param {Object} options
   * @param {string} options.startHHmm
   * @param {string} options.halfLifeHHmm
   * @param {string} options.endHHmm
   * @param {number} options.partRatio
   */
  constructor ({ startHHmm = '00:00', onsetHHmm = '00:00', peakHHmm = '00:30', halfLifeHHmm, durationHHmm, partRatio = 1 }) {
    const startMs = Time.fromHHmm(startHHmm)
    const durationMs = Time.fromHHmm(durationHHmm)
    super({ startMs, endMs: startMs + durationMs })
    this.onsetMs = Time.fromHHmm(onsetHHmm)
    this.peakMs = Time.fromHHmm(peakHHmm)
    this.halfLifeMs = Time.fromHHmm(halfLifeHHmm)
    this.durationMs = durationMs
    this.partRatio = partRatio
  }

  set onsetMs (value) {
    this._onsetMs = value
  }

  /** @type {[Time]} */
  get onsetMs () {
    return this._onsetMs
  }

  set peakMs (value) {
    this._peakMs = value
  }

  /** @type {[Time]} */
  get peakMs () {
    return this._peakMs
  }

  set halfLifeMs (value) {
    this._halfLifeMs = value
  }

  /** @type {[Time]} */
  get halfLifeMs () {
    return this._halfLifeMs
  }

  set durationMs (value) {
    this._durationMs = value
  }

  /** @type {[Time]} */
  get durationMs () {
    return this._durationMs
  }

  set partRatio (value) {
    this._partRatio = value
  }

  /** @type {number} */
  get partRatio () {
    return this._partRatio
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {number}
   */
  getRemainingIntensityAt ({ ms }) {
    return 1 - this.getPassedIntensityAt({ ms })
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {number}
   */
  getPassedIntensityAt ({ ms }) {
    // todo: double peaks
    let { startMs, onsetMs, peakMs, halfLifeMs, durationMs } = this
    startMs = Number(startMs) // start in profile
    onsetMs = Number(onsetMs)
    peakMs = Number(peakMs)
    halfLifeMs = Number(halfLifeMs)
    durationMs = Number(durationMs)
    const endMs = durationMs + startMs // end in profile

    if (ms < startMs) return 0
    if (ms > endMs) return 1

    const progressMs = ms - startMs

    const onsetPeakDurationMs = peakMs - onsetMs
    const onsetPeakProgressMs = progressMs - onsetMs

    const halfLifeProgressMs = progressMs - peakMs

    const peakRatio = 0.5

    const isAfterEndMs = (progressMs >= durationMs)
    const isBeforeOnsetPeakMs = (progressMs <= onsetMs)

    if (isAfterEndMs) return 1
    if (isBeforeOnsetPeakMs) return 0

    const isInOnsetPeakMs = (onsetPeakProgressMs >= 0 && onsetPeakProgressMs <= onsetPeakDurationMs)
    const isInHalfLifeMs = (halfLifeProgressMs >= 0)

    if (isInOnsetPeakMs) {
      const tanAngle = peakRatio / onsetPeakDurationMs
      const intensity = (tanAngle * onsetPeakProgressMs)
      return intensity
    }

    if (isInHalfLifeMs) {
      const intensity = peakRatio + peakRatio - (peakRatio * (1 / (Math.pow(2, halfLifeProgressMs / halfLifeMs))))
      return intensity
    }

    return 1
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {number}
   */
  getIntensityAt ({ ms }) {
    // todo: double peaks
    let { startMs, onsetMs, peakMs, halfLifeMs, durationMs } = this
    startMs = Number(startMs) // start in profile
    onsetMs = Number(onsetMs)
    peakMs = Number(peakMs)
    halfLifeMs = Number(halfLifeMs)
    durationMs = Number(durationMs)
    const endMs = durationMs + startMs // end in profile

    if (ms < startMs || ms > endMs) return 0
    const progressMs = ms - startMs

    const onsetPeakDurationMs = peakMs - onsetMs
    const onsetPeakProgressMs = progressMs - onsetMs

    const halfLifeProgressMs = progressMs - peakMs

    const peakRatio = 0.5

    const isAfterEndMs = (progressMs >= durationMs)
    const isBeforeOnsetPeakMs = (progressMs <= onsetMs)

    if (isAfterEndMs || isBeforeOnsetPeakMs) return 0

    const isInOnsetPeakMs = (onsetPeakProgressMs >= 0 && onsetPeakProgressMs <= onsetPeakDurationMs)
    const isInHalfLifeMs = (halfLifeProgressMs >= 0)

    if (isInOnsetPeakMs) {
      const tanAngle = peakRatio / onsetPeakDurationMs
      const intensity = (tanAngle * onsetPeakProgressMs)
      return intensity
    }

    if (isInHalfLifeMs) {
      const intensity = (peakRatio * (1 / (Math.pow(2, halfLifeProgressMs / halfLifeMs))))
      return intensity
    }

    return 0
  }
}
