import EffectProfile from './EffectProfile.js'
import Timeline from './Timeline.js'

export default class TypeOneAnalysis {
  set effectProfiles (value) {
    this._effectProfiles = value
  }

  /** @type {[EffectProfile]} */
  get effectProfiles () {
    return this._effectProfiles
  }

  /**
   * @param {Object} options
   * @param {Object} options.data
   * @returns {TypeOneAnalysis}
   */
  setEffectProfiles ({ data }) {
    this.effectProfiles = data.map(ep => new EffectProfile(ep))
    return this
  }

  /**
   * @param {Object} options
   * @param {Array<Object>} options.data
   * @returns {Timeline}
   */
  timeline ({ data }) {
    data = data.slice(0)
    const timeline = new Timeline({ effectProfiles: this.effectProfiles })
    data.sort((a, b) => a.date - b.date)
    data.forEach(row => timeline.add(row))
    timeline.order()
    return timeline
  }
}
